import os
import json
import logging
import pandas as pd
import numpy as np
from pathlib import Path
from typing import Tuple, List

from config import load_config_from_file

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger('llmXive.splitter')

def load_processed_data() -> pd.DataFrame:
    """Load the processed metrics file generated by T006."""
    config = load_config_from_file('config.json')
    path = Path(config['data']['processed']) / 'metrics_with_moves.csv'
    if not path.exists():
        logger.error(f"Source file {path} not found. Ensure T006 has run successfully.")
        return pd.DataFrame()
    
    df = pd.read_csv(path)
    logger.info(f"Loaded {len(df)} rows from {path}")
    return df

def stratified_split(df: pd.DataFrame) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """
    Split data into Train, Ablation-Train, Validation, and Test sets.
    
    Strategy:
    1. Identify unique trajectories.
    2. Stratify based on 'outcome' (win/loss) if available, otherwise random.
    3. Reserve Validation set first (min 20 trajectories).
    4. Split remaining into Train, Ablation-Train, and Test.
    
    Returns:
        Tuple of (train_df, ablation_train_df, val_df, test_df)
    """
    if df.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    # Ensure we have a trajectory_id column
    if 'trajectory_id' not in df.columns:
        raise ValueError("Input DataFrame must contain 'trajectory_id' column.")

    # Group by trajectory_id to get unique trajectories
    unique_trajectories = df['trajectory_id'].unique()
    n_trajectories = len(unique_trajectories)
    
    if n_trajectories == 0:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    # Determine stratification column
    stratify_col = None
    if 'outcome' in df.columns:
        stratify_col = 'outcome'
    
    # Map trajectory_id to its outcome (take the first occurrence for each trajectory)
    traj_outcomes = df.groupby('trajectory_id')[stratify_col].first().reset_index() if stratify_col else None

    # Shuffle trajectories
    np.random.seed(42)
    shuffled_trajs = np.random.permutation(unique_trajectories)

    # Calculate split sizes
    # Validation: at least 20, or 10% of total, whichever is larger, but not exceeding 80%
    val_size = max(20, int(n_trajectories * 0.1))
    val_size = min(val_size, int(n_trajectories * 0.8))
    
    # Test: 20% of remaining
    remaining_after_val = n_trajectories - val_size
    test_size = int(remaining_after_val * 0.2)
    
    # Train + Ablation Train: rest
    train_plus_ablation_size = remaining_after_val - test_size
    
    # Split Train vs Ablation Train (50/50 of this remainder)
    ablation_train_size = int(train_plus_ablation_size * 0.5)
    train_size = train_plus_ablation_size - ablation_train_size

    # Assign trajectories to sets
    val_trajs = shuffled_trajs[:val_size]
    test_trajs = shuffled_trajs[val_size : val_size + test_size]
    ablation_train_trajs = shuffled_trajs[val_size + test_size : val_size + test_size + ablation_train_size]
    train_trajs = shuffled_trajs[val_size + test_size + ablation_train_size :]

    # Filter the original dataframe
    val_df = df[df['trajectory_id'].isin(val_trajs)].copy()
    test_df = df[df['trajectory_id'].isin(test_trajs)].copy()
    ablation_train_df = df[df['trajectory_id'].isin(ablation_train_trajs)].copy()
    train_df = df[df['trajectory_id'].isin(train_trajs)].copy()

    logger.info(f"Split complete: Train={len(train_df)}, Ablation-Train={len(ablation_train_df)}, Validation={len(val_df)}, Test={len(test_df)}")
    
    # Final validation
    if len(val_df) < 20:
        raise ValueError(f"Validation set size {len(val_df)} is less than required 20 (FR-006).")

    return train_df, ablation_train_df, val_df, test_df

def save_split_data():
    """Save the split datasets to CSV and validation IDs to JSON."""
    config = load_config_from_file('config.json')
    out_dir = Path(config['data']['processed'])
    
    # Ensure output directory exists
    out_dir.mkdir(parents=True, exist_ok=True)
    
    df = load_processed_data()
    if df.empty:
        logger.warning("No data to split. Creating empty output files.")
        for name in ['train_set', 'ablation_train_set', 'validation_set', 'test_set']:
            pd.DataFrame().to_csv(out_dir / f'{name}.csv', index=False)
        with open(out_dir / 'validation_set_ids.json', 'w') as f:
            json.dump([], f)
        return

    train_df, ablation_train_df, val_df, test_df = stratified_split(df)
    
    # Save CSVs
    train_df.to_csv(out_dir / 'train_set.csv', index=False)
    ablation_train_df.to_csv(out_dir / 'ablation_train_set.csv', index=False)
    val_df.to_csv(out_dir / 'validation_set.csv', index=False)
    test_df.to_csv(out_dir / 'test_set.csv', index=False)
    
    # Save validation set IDs
    validation_ids = val_df['trajectory_id'].unique().tolist()
    with open(out_dir / 'validation_set_ids.json', 'w') as f:
        json.dump(validation_ids, f)
    
    logger.info(f"Split data saved to {out_dir}")
    logger.info(f"Validation set IDs saved ({len(validation_ids)} trajectories)")

def validate_split():
    """Validate the split integrity."""
    config = load_config_from_file('config.json')
    out_dir = Path(config['data']['processed'])
    
    files = ['train_set.csv', 'ablation_train_set.csv', 'validation_set.csv', 'test_set.csv']
    for f in files:
        path = out_dir / f
        if not path.exists():
            logger.error(f"Missing split file: {path}")
            return False
        
    # Check for ID overlap
    all_ids = set()
    for f in files:
        path = out_dir / f
        df = pd.read_csv(path)
        current_ids = set(df['trajectory_id'].unique())
        if all_ids.intersection(current_ids):
            logger.error(f"Overlap detected in {f}")
            return False
        all_ids.update(current_ids)
        
    logger.info("Split validation passed.")
    return True

def main():
    save_split_data()
    validate_split()

if __name__ == '__main__':
    main()